/**
 * A Storybook preset that points the components manifest's imports, which
 * agents read, at the components barrel: every component is a named export
 * there, including those that aren't their file's default export.
 */

import { readFileSync } from 'node:fs';

import type { Manifests } from 'storybook/internal/types';

// Written by `pnpm create-autogenerated-files`. Read on every call, so the
// dev server picks up a component added while it runs.
const barrelExports = () =>
  new Set(
    [
      ...readFileSync(
        new URL('../src/components.ts', import.meta.url),
        'utf8',
      ).matchAll(/export \{([^}]*)\}/g),
    ].flatMap((match) =>
      (match[1] ?? '')
        .split(',')
        .map((name) => name.replace(/^\s*default as /, '').trim()),
    ),
  );

export const experimental_manifests = (manifests: Manifests | undefined) => {
  const exported = barrelExports();
  for (const component of Object.values(
    manifests?.components?.components ?? {},
  )) {
    if (exported.has(component.name)) {
      component.import = `import { ${component.name} } from 'carbon-components-ember/components';`;
    }
  }
  return manifests;
};
